class TestParseLogLine:
    def test_valid_error_log_line(self):
        line = "2024-01-15 10:30:45 ERROR [auth] Login failed for user admin"
        assert parse_log_line(line) == {
            "date": "2024-01-15",
            "time": "10:30:45",
            "level": "ERROR",
            "module": "auth",
            "message": "Login failed for user admin",
        }

    @pytest.mark.parametrize("level", ["INFO", "WARN", "ERROR", "DEBUG"])
    def test_all_valid_levels(self, level):
        line = f"2024-01-15 10:30:45 {level} [core] message"
        result = parse_log_line(line)

        assert result is not None
        assert result["date"] == "2024-01-15"
        assert result["time"] == "10:30:45"
        assert result["level"] == level
        assert result["module"] == "core"
        assert result["message"] == "message"

    def test_empty_string_returns_none(self):
        assert parse_log_line("") is None

    @pytest.mark.parametrize(
        "line",
        [
            "2024-01-15",
            "2024-01-15 10:30:45",
            "2024-01-15 10:30:45 ERROR",
            "2024-01-15 10:30:45 ERROR [auth]",
        ],
    )
    def test_missing_fields_returns_none(self, line):
        assert parse_log_line(line) is None

    @pytest.mark.parametrize(
        "line",
        [
            "2024-01-15 10:30:45 CRITICAL [auth] message",
            "2024-01-15 10:30:45 WARNING [auth] message",
            "2024-01-15 10:30:45 error [auth] message",
            "2024-01-15 10:30:45 info [auth] message",
            "2024-01-15 10:30:45 TRACE [auth] message",
        ],
    )
    def test_invalid_log_level_returns_none(self, line):
        assert parse_log_line(line) is None

    @pytest.mark.parametrize(
        "module_raw, expected_module",
        [
            ("[auth]", "auth"),
            ("[system]", "system"),
            ("[database]", "database"),
            ("[module-name]", "module-name"),
        ],
    )
    def test_module_name_extraction_with_brackets(self, module_raw, expected_module):
        line = f"2024-01-15 10:30:45 INFO {module_raw} message"
        result = parse_log_line(line)

        assert result is not None
        assert result["module"] == expected_module

    def test_module_without_brackets_is_returned_as_is(self):
        line = "2024-01-15 10:30:45 INFO auth message"
        result = parse_log_line(line)

        assert result is not None
        assert result["module"] == "auth"

    def test_multiple_spaces_in_message_are_preserved(self):
        line = "2024-01-15 10:30:45 ERROR [auth]  hello   world"
        result = parse_log_line(line)

        assert result is not None
        assert result["message"] == " hello   world"

    def test_message_with_trailing_spaces_is_preserved(self):
        line = "2024-01-15 10:30:45 ERROR [auth] hello  "
        result = parse_log_line(line)

        assert result is not None
        assert result["message"] == "hello  "

    def test_leading_space_makes_line_malformed(self):
        line = " 2024-01-15 10:30:45 ERROR [auth] message"
        assert parse_log_line(line) is None

