interface Preferences {
  theme: string;
  notifications: boolean;
  language: string;
}

interface User {
  id: number;
  name: string;
  email: string;
  preferences: Preferences;
  tags: string[];
  last_login: string;
  metadata?: string | null;
}

function validateUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const user = value as Record<string, unknown>;

  if (!Number.isInteger(user.id)) {
    return false;
  }

  if (typeof user.name !== "string" || user.name.length === 0) {
    return false;
  }

  if (typeof user.email !== "string" || !user.email.includes("@")) {
    return false;
  }

  if (typeof user.preferences !== "object" || user.preferences === null) {
    return false;
  }

  const preferences = user.preferences as Record<string, unknown>;

  if (typeof preferences.theme !== "string") {
    return false;
  }

  if (typeof preferences.notifications !== "boolean") {
    return false;
  }

  if (typeof preferences.language !== "string") {
    return false;
  }

  if (
    !Array.isArray(user.tags) ||
    !user.tags.every((tag) => typeof tag === "string")
  ) {
    return false;
  }

  if (typeof user.last_login !== "string") {
    return false;
  }

  if (
    user.metadata !== undefined &&
    user.metadata !== null &&
    typeof user.metadata !== "string"
  ) {
    return false;
  }

  return true;
}
