#!/usr/bin/env python3
"""
CLI tool to summarize log levels in .log files.

Usage:
    python log_summary.py /path/to/logs
    python log_summary.py /path/to/logs --min-errors 5
"""

import argparse
import re
import sys
from pathlib import Path

LEVELS = ("INFO", "WARN", "ERROR", "DEBUG")

# Match the first standalone log-level token in a line.
LEVEL_RE = re.compile(r"\b(DEBUG|INFO|WARN|ERROR)\b", re.IGNORECASE)


def count_levels(path):
    """Count log-level occurrences in a single file."""
    counts = {level: 0 for level in LEVELS}

    try:
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                match = LEVEL_RE.search(line)
                if match:
                    counts[match.group(1).upper()] += 1
    except OSError as exc:
        print(f"Warning: could not read {path}: {exc}", file=sys.stderr)

    return counts


def format_table(rows):
    """Format and return a summary table as a string."""
    headers = ("file", "INFO", "WARN", "ERROR", "DEBUG")

    table = [headers]
    for file_name, info, warn, error, debug in rows:
        table.append((file_name, str(info), str(warn), str(error), str(debug)))

    widths = [max(len(row[i]) for row in table) for i in range(len(headers))]

    lines = []
    for i, row in enumerate(table):
        if i == 1:
            lines.append("-+-".join("-" * width for width in widths))
        lines.append(" | ".join(cell.ljust(widths[j]) for j, cell in enumerate(row)))

    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(
        description="Count INFO, WARN, ERROR, and DEBUG occurrences in .log files."
    )

    parser.add_argument(
        "directory",
        help="Directory containing .log files",
    )

    parser.add_argument(
        "--min-errors",
        type=int,
        default=0,
        metavar="N",
        help="Only show files with at least N ERROR entries",
    )

    args = parser.parse_args()

    if args.min_errors < 0:
        parser.error("--min-errors must be a non-negative integer")

    directory = Path(args.directory)

    if not directory.is_dir():
        parser.error(f"Directory not found: {directory}")

    log_files = sorted(
        path
        for path in directory.iterdir()
        if path.is_file() and path.suffix.lower() == ".log"
    )

    rows = []

    for path in log_files:
        counts = count_levels(path)

        if counts["ERROR"] >= args.min_errors:
            rows.append(
                (
                    path.name,
                    counts["INFO"],
                    counts["WARN"],
                    counts["ERROR"],
                    counts["DEBUG"],
                )
            )

    print(format_table(rows))

    if not rows:
        print(f"No .log files matched with at least {args.min_errors} ERROR(s).")


if __name__ == "__main__":
    main()
